const menuButton=document.querySelector('.menu-button');const nav=document.querySelector('#main-nav');menuButton.addEventListener('click',()=>{const open=nav.classList.toggle('open');menuButton.setAttribute('aria-expanded',String(open))});nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}));
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function hydrate(){try{const [properties,posts]=await Promise.all([fetch('/api/properties').then(r=>r.ok?r.json():[]),fetch('/api/posts').then(r=>r.ok?r.json():[])]);if(properties.length){document.querySelector('.property-grid').innerHTML=properties.map((p,i)=>`<article class="property-card ${p.featured?'featured':''}"><div class="property-image" style="background-image:url('${escapeHtml(p.image_url||'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1000&q=85')}')"><span>${escapeHtml(p.status==='published'?p.purpose:p.status)}</span></div><div class="property-copy"><p class="property-type">${escapeHtml(p.property_type)}</p><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.description)}</p><div class="property-meta"><span>${escapeHtml(p.location)}</span><a href="#contact">Enquire →</a></div></div></article>`).join('')}if(posts.length){document.querySelector('.blog-grid').innerHTML=posts.slice(0,4).map(p=>`<article><div class="blog-image" style="background-image:url('${escapeHtml(p.image_url||'https://images.unsplash.com/photo-1560518883-ce09059eeffa?auto=format&fit=crop&w=1100&q=85')}')"></div><p class="date">${escapeHtml(p.category)} · ${new Date(p.published_at||p.created_at).toLocaleDateString()}</p><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.excerpt)}</p><a href="#contact">Read article →</a></article>`).join('')}}catch{}}
document.querySelector('#booking-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,status=form.querySelector('.form-status');status.textContent='Sending…';try{const r=await fetch('/api/enquiries',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(!r.ok)throw new Error();status.textContent='Thank you. Your appointment request has been received.';form.reset()}catch{status.textContent='Please call +233 55 247 5643 to complete your request.'}});hydrate();
